// AdmissionRequest 结构（Go 定义）
type AdmissionRequest struct {
    // 操作类型: CREATE, UPDATE, DELETE, CONNECT
    Operation string

    // 用户信息
    UserInfo struct {
        Username string              // 用户名
        UID      string              // 用户 UID
        Groups   []string            // 用户组列表
        Extra    map[string][]string // 额外信息
    }

    // 资源信息
    Kind struct {
        Group   string
        Version string
        Kind    string
    }

    // 命名空间
    Namespace string

    // 资源名称
    Name string

    // DryRun 标志
    DryRun bool

    // 子资源（如 status, scale）
    SubResource string
}
